tools.usage:
#usage "<description shown in the Control Panel>"
// definitions: enum constants, variables, functions
// statements: executed top to bottom (or define: int main() { ... })
if (board) board(B) { ... }            // open a data context
output("file.txt", "wt") { printf(...); }  // write a file
exit("EDITOR COMMAND;");                // optional: commands run after RUN

tools.example:
#usage "Counts the elements of the current board\n"
       "Usage: RUN count-elements.ulp"

int CountElements()
{
  int n = 0;
  board(B) B.elements(E) ++n;
  return n;
}

if (!board) {
   dlgMessageBox(":Start this ULP from a board window.");
   exit(1);
   }
string msg;
sprintf(msg, "The board has %d elements.", CountElements());
dlgMessageBox(msg);

