tools.example:
int CountDots(string s)
{
  int dots = 0;
  for (int i = 0; s[i]; ++i)
      if (s[i] == '.') ++dots;
  return dots;
}

void WriteLine(string name, real x, real y)
{
  printf("%s;%.3f;%.3f\n", name, x, y);   // goes to the active output() file
}

// & binds weaker than ==, so parenthesize flag tests:
board(B) output("nostop.txt", "wt") B.elements(E) E.footprint.contacts(C)
  if (C.pad && (C.pad.flags & PAD_FLAG_STOP) == 0)
     printf("%s.%s has no stop mask\n", E.name, C.name);

int n = 0;
