// iterate the positive partial polygons of a calculated signal polygon
board(B) B.signals(S) S.polygons(P) {
  int i = 1, active;
  do {
     active = 0;
     P.contours(W, i) { active = 1; /* use W */ }
     ++i;
     } while (active);
  }

