if (schematic) schematic(SCH) {
   output(filesetext(SCH.name, ".bom.txt"), "wt") {
     SCH.allparts(P)                       // includes virtual parts of module instances
       if (P.device.footprint && P.populate)
          printf("%-8s %-12s %s\n", P.name, P.value, P.device.footprint.name);
     }
   }

if (library) library(L) {
   output(filesetext(L.name, ".txt"), "wt") {
     L.devicesets(DS) {
       printf("%s (prefix %s)\n", DS.name, DS.prefix);
       DS.devices(D)
         printf("  %s -> %s\n", D.name, D.footprint ? D.footprint.name : "(no footprint)");
       }
     }
   }

if (deviceset) deviceset(DS) {
   string s = DS.name + " gates:";
   DS.gates(G) s += " " + G.name + "(" + G.symbol.name + ")";
   if (DS.activedevice) s += "\nactive variant: " + DS.activedevice.name;
   dlgMessageBox(s);
   }

if (symbol) symbol(S) {
   output("pins.txt", "wt")
     S.pins(P)
       printf("%s\t%.2f\t%.2f\tdir=%d\n", P.name, u2mm(P.x), u2mm(P.y), P.direction);
   }

if (sheet) sheet(SH) {
   output("sheet-nets.txt", "wt") {
     printf("Sheet %d\n", SH.number);
     SH.nets(N) N.segments(SEG) SEG.pinrefs(P)
       printf("%s: %s.%s\n", N.name, P.part.name, P.pin.name);
     }
   }

if (module) module(M) {
   string s = "Module " + M.name + " ports:";
   M.ports(P) s += " " + P.name;
   dlgMessageBox(s);
   }
else dlgMessageBox("No module is being edited.");

#require 9.0100
if (footprint) footprint(F) {
   int pads = 0, smds = 0;
   F.contacts(C) { if (C.pad) ++pads; else if (C.smd) ++smds; }
   string s;
   sprintf(s, "%s: %d pads, %d SMDs", F.name, pads, smds);
   dlgMessageBox(s);
   }

board(B) {
  string File = dlgFileSave("Save part list", filesetext(B.name, ".csv"), "*.csv");
  if (!File) exit(0);
  fileerror();
  output(File, "wt") {
    printf("Name;Value;Package\n");
    B.elements(E) printf("%s;%s;%s\n", E.name, E.value, E.footprint.name);
    }
  if (fileerror()) exit(1);
  }
